window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-sangramento-uterino-anormal-sua"]={"block":"anki:ginecologia-sangramento-uterino-anormal-sua","label":"Anki · Sangramento Uterino Anormal (SUA)","count":95,"questions":[{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-936a6602ba562268","number":"0201h","sourceNumber":"0201h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 62 anos de idade, menopausada há 10 anos, sem uso de Terapia Hormonal. Começou a apresentar sangramento genital intermitente, de moderada a grande quantidade. Ao exame especular, seu colo uterino não apresentava lesão e foi visto que este sangramento era proveniente do útero. É obesa, diabética e hipertensa. Foi submetida a ultrassonografia pélvica, que mostrou espessamento endometrial (linha endometrial de 2,1cm). Sendo sua hipótese um Sangramento Uterino Anormal (SUA), qual das alternativas abaixo é uma hipótese diagnóstica para essa paciente?","options":{"A":"SUA-a (por adenomiose)","B":"SUA-c (por coagulopatia)","C":"SUA-m (por malignidade ou hiperplasia do endométrio)","D":"SUA-o (por disfunção ovulatória)"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234383","ankiGuid":"lP),{W8rlE"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-3b35bbe4eb92e41a","number":"0202h","sourceNumber":"0202h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Uma paciente de 48 anos de idade, tabagista, com antecedente familiar de trombose, refere miomatose uterina diagnosticada há cinco anos e queixa de irregularidade menstrual e menorragia há um ano, associada à dismenorreia nos dias de fluxo menstrual mais intenso. Refere ainda ondas de calor esporádicas, sem prejuízo da qualidade de vida. Nega doenças crônicas e uso de medicações. No momento, sem sangramento. Ao exame, paciente em bom estado geral, corada, hidratada e com abdome flácido e indolor. Especular sem alterações. Ao toque vaginal, útero pouco aumentado de tamanho, com cerca de 11 cm no maior eixo, contornos irregulares e indolor à mobilização. Anexos não palpáveis. Realizou USG, que evidenciou útero em anteversoflexão, com volume de 198 cm³ , miométrio heterogêneo às custas de quatro formações nodulares, hipoecogênicas, medindo até 3 cm, subserosos com menos de 50% de penetração no miométrio e outro nódulo de 2 cm intramural em parede fúndica, sem contato com linha endometrial. Com base nesse caso hipotético, assinale a alternativa que apresenta a conduta mais adequada.","options":{"A":"progestágeno de segunda fase","B":"anticoncepcional oral combinado","C":"anti-inflamatório e ácido tranexâmico","D":"miomectomia laparotômica","E":"histerectomia laparoscópica"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234384","ankiGuid":"m?&9G,VNf4"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-b2623f14abde19dc","number":"0203h","sourceNumber":"0203h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"JABB, 43 anos, apresenta sangramento uterino anormal. Nessa faixa etária, a causa mais comum é:","options":{"A":"Síndrome dos ovários policísticos.","B":"Miomatose uterina.","C":"Pólipos endometriais.","D":"Câncer de endométrio.","E":"Câncer de colo uterino."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234385","ankiGuid":"H$gR2RUv3B"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-7dc529ccc426dd27","number":"0204h","sourceNumber":"0204h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"A teoria que explica o sangramento intermenstrual discreto e limitado que acontece em mulheres não usuárias de anticoncepção hormonal é:","options":{"A":"aumento no nível de progesterona circulante causando atrofia endometrial.","B":"diminuição abrupta no nível de prolactina.","C":"falha na ovulação com conseqüente disfunção de corpo lúteo.","D":"queda do nível de estrogênio logo após o pico desse mesmo hormônio."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234386","ankiGuid":"nbZb#mtlgQ"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-db665efee0413598","number":"0205h","sourceNumber":"0205h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Em 2011 a FIGO desenvolveu um sistema de classificação para causas de sangramento uterino anormal em mulheres não grávidas em idade reprodutiva denominada PALM-COEIN. Fazem parte das causas classificadas como estruturais:","options":{"A":"Pólipo e coagulopatia;","B":"SOP e leiomioma;","C":"Câncer de endométrio e adenomiose;","D":"Hiperplasia endometrial e induzidas por medicação."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234387","ankiGuid":"Iro29qD>iW"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-b02c0df23c73dac7","number":"0206h","sourceNumber":"0206h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 40 anos apresenta sangramento menstrual excessivo com o seguinte achado histeroscópico:\n\nQual é o tratamento mais adequado?","options":{"A":"Dispositivo intrauterino com progesterona.","B":"Ácido tranexâmico.","C":"Embolização.","D":"Ablação histeroscópica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":["question_bank/media/ginecologia-sangramento-uterino-anormal-sua/paste-f861e933b9eaaadeab948fb86529770f3d2bbd40.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234388","ankiGuid":"ozkT>;4yDc"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-1068efaf40f78ddd","number":"0207h","sourceNumber":"0207h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 45 anos de idade, com sangramento genital em grande quantidade, há 3 dias. Ao exame, encontra-se descorada, porém normotensa. O exame físico mostra presença de grande quantidade de sangue e coágulos na vagina, sem lesões visíveis. A ultrassonografia pélvica mostra útero e ovários normais. As medicações que podem melhorar o sangramento genital nesse momento são","options":{"A":"corticoides, anti-inflamatórios não hormonais ou contraceptivos injetáveis.","B":"estrogênios, anti-inflamatórios ou antifibrinolíticos.","C":"progesterona vaginal, análogos de GnRh, albumina endovenosa.","D":"análogos de GnRH, contraceptivos hormonais de progestagênio ou combinados.","E":"implante de progesterona, progesterona oral ou fibrinolíticos."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234389","ankiGuid":"p5.!p@jpXe"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-c0bdcaa1bce33453","number":"0208h","sourceNumber":"0208h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"A.L.F., 57 anos, com história de pequeno sangramento pós-menopausa. Exame físico sem alterações. Fez uma ultrassonografia transvaginal que evidenciou um eco endometrial homogêneo medindo 2 mm. Qual o provável diagnóstico e a conduta mais adequada, respectivamente?","options":{"A":"Câncer de endométrio e curetagem uterina","B":"Pólipo endometrial e histeroscopia","C":"Hiperplasia endometrial e biópsia","D":"Sangramento disfuncional e reposição hormonal","E":"Atrofia endometrial e acompanhamento"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234390","ankiGuid":"h<h=e3&v[4"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-45f3dc62828a6807","number":"0209h","sourceNumber":"0209h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"O sangramento uterino anormal de causa endometrial (SUA-E), de característica intermenstrual, pode ser consequência de infecção uterina (endometrite) por:","options":{"A":"Cândida albicans.","B":"Estreptococo.","C":"Clamídia.","D":"Pseudômonas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234391","ankiGuid":"i6w?`Y2F%/"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-4350e22ef3695b94","number":"0210h","sourceNumber":"0210h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Em pacientes na pós-menopausa sem reposição hormonal, a causa mais frequente de sangramento uterino anormal é:","options":{"A":"Atrofia endometrial.","B":"Pólipo de endométrio.","C":"Hiperplasia endometrial.","D":"Carcinoma de endométrio."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234392","ankiGuid":"xQ[S+&.:U8"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-4113a9190f587c28","number":"0211h","sourceNumber":"0211h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"A hipótese diagnóstica mais provável de sangramento uterino anormal na adolescência é:","options":{"A":"miomatose","B":"anovulação","C":"adenomiose","D":"pólipo endometrial"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234393","ankiGuid":"lknleO[a1?"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-b7db527943b53a45","number":"0212h","sourceNumber":"0212h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Tratamento do sangramento uterino anormal agudo SGA, 50 anos é atendida em emergência com queixa de volumoso sangramento via vaginal, coágulos e tonteira. Ao exame físico a paciente apresentava-se com anemia importante. Após exames complementares de urgência foram excluídas causas orgânicas e o caso foi classificado como sangramento uterino disfuncional (SUD). A melhor opção para o tratamento clínico da menorragia aguda é","options":{"A":"ácido mefenâmico, 500mg, 3 vezes ao dia por 5 dias iniciando junto com a menstruação.","B":"sistema intrauterino liberador de levonorgestrel.","C":"estrogênios equinos conjugados, 2,5mg, 6/6hs até a melhora do sangramento.","D":"noretindrona, 5mg, 3 vezes ao dia, do 15º ao 26º dias do ciclo.","E":"contraceptivos orais combinados, 1 vez ao dia até a melhora do sangramento."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234394","ankiGuid":"vvGs7W5}*F"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-a451a69dd112baa8","number":"0213h","sourceNumber":"0213h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Ovulatório Distúrbios Paciente de 41 anos apresenta sangramento uterino volumoso, porém com ciclos regulares, e se encontra estável hemodinamicamente. Os exames de imagem (ultrassonografia e histeroscopia com biópsia) mostram útero sem lesões estruturais. Não foram identificadas coagulopatias, lesões endometriais ou causas iatrogênicas. O diagnóstico provável do sangramento e uma terapia não hormonal, para o caso em questão, respectivamente, são:","options":{"A":"adenomiose / ácido mefenâmico","B":"disfuncional / ácido tranexâmico","C":"adenomiose / valerato de estradiol","D":"disfuncional / acetato de medroxiprogesterona"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234395","ankiGuid":"lT>uly!!v)"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-22002dc75424660f","number":"0214h","sourceNumber":"0214h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente com 65 anos, nuligesta, menopausa há 15 anos. É hipertensa controlada. Peso = 58Kg e altura = 1,52m. Fez reposição hormonal com estrogênio e progesterona por 5 anos, tendo suspendido há 10 anos. Com sangramento vaginal há 3 meses, em pequena quantidade e com duração de 1-2 dias. Exame especular: sangue pelo orifício externo do colo uterino. Pode-se afirmar que a causa mais frequente deste sangramento é:","options":{"A":"carcinoma de endométrio","B":"pólipo endometrial","C":"terapia de reposição hormonal","D":"atrofia endometrial"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234396","ankiGuid":"Iv>cob4-y]"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-3fb98f7c36ff4100","number":"0215h","sourceNumber":"0215h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Distúrbios Na hemorragia uterina disfuncional a melhor opção de tratamento é:","options":{"A":"Curetagem Uterina","B":"Medicamentos","C":"Abalação endometrial","D":"Histerectomia","E":"Transfusão sanguínea"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234397","ankiGuid":"x?8~%u^4t?"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-240effc31b424af0","number":"0216h","sourceNumber":"0216h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher, 36 anos, com sangramento vaginal de início hoje, comparece na emergência. Hipocorada 2+/4, frequência cardíaca 110 bpm, pressão arterial 90x60 mmHg. Abdômen sem massas e indolor. Exame especular com colo epitelizado e sangramento intenso exteriorizando pelo orifício externo do colo. Toque vaginal com útero intrapélvico, indolor a mobilização. Beta HCG negativo. Ultrassom transvaginal com mioma submucoso de 4 cm. Qual a conduta imediata, além de hidratação venosa e solicitação de reserva de sangue?","options":{"A":"Histeroscopia com miomectomia.","B":"Curetagem uterina.","C":"Valerato de estradiol 2mg de 6 em 6 horas.","D":"Noretisterona 10 mg por dia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234398","ankiGuid":"pVIH=4.XJm"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-5933077e5efdc15a","number":"0217h","sourceNumber":"0217h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Assinale a alternativa incorreta em relação sangramento uterino anormal (SUA):","options":{"A":"A biópsia endometrial deve ser realizada em todas as pacientes com sua e com mais de 45 anos, falha terapêutica ou ultrassonografia transvaginal com endométrio irregular","B":"O objetivo do tratamento é manejar a fase aguda e estabilizar o quadro clínico da paciente, corrigindo a alteração menstrual e a anemia e conduta expectante para os próximos ciclos","C":"O sua é caraterizado pela frequência, regularidade, duração e volume","D":"A ablação endometrial é um procedimento cirúrgico para aquelas mulheres com contraindicação para terapêutica hormonal","E":"São contraindicações para o tratamento hormonal: tabagismo e idade superior a 35 anos, câncer de mama, enxaqueca com aura"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234399","ankiGuid":"rtq!0esKi:"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-0f693f969149725f","number":"0218h","sourceNumber":"0218h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher de 25 anos, solteira, sem parceiro sexual fixo, sexualmente ativa, refere uso ocasional de preservativos. Procura atendimento ginecológico por queixa de sangramento vaginal irregular, com ciclos menstruais prévios regulares, sem uso de método anticoncepcional. Na investigação de sangramento uterino anormal, neste caso, o PRIMEIRO exame a ser solicitado é:","options":{"A":"TGO/TGP","B":"Ultrassom transvaginal","C":"Ressonância magnética da pelve","D":"Creatinina sérica","E":"B-hCG"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234400","ankiGuid":"J65Z6NT>TE"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-ee260be8ceb0c2ba","number":"0219h","sourceNumber":"0219h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Em relação ao sangramento uterino anormal (SUA), atribua V (verdadeiro) ou F (falso) às afirmativas a seguir. ( ) Sangramento intermenstrual é a manifestação clínica mais comum dos pólipos endometriais. ( ) O sangramento uterino irregular é mais comumente associado à disfunção ovulatória. ( ) As malformações arteriovenosas uterinas são causas frequentes do SUA. ( ) Os distúrbios de coagulação, geralmente se apresentam como sangramento intenso na menarca ou nas mulheres em seus últimos anos reprodutivos. ( ) A doença inflamatória pélvica (DIP) com endometrite é uma etiologia rara de SUA. Assinale a alternativa que contém, de cima para baixo, a sequência correta.","options":{"A":"V, V, F, F, V.","B":"V, F, V, F, V.","C":"F, V, V, V, F.","D":"F, V, F, F, V.","E":"F, F, V, V, F."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234401","ankiGuid":"riAQsG{AN@"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-a6c0e846553e32f3","number":"0220h","sourceNumber":"0220h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Uma paciente com 58 anos, G2P2A0, aposentada, chega ao pronto-socorro com sangramento uterino anormal iniciado há um dia. Relata menopausa há três anos, sem uso de TH. A sua última consulta ginecológica foi há três anos, com rotina de exames ginecológicos normais. Diabética e hipertensa, faz uso de hipoglicemiante oral e anti-hipertensivo; porém, de forma irregular. Ao exame clínico, constatou-se bom estado geral; PA: 140X90mmHg; pulso de 88bpm; aparelho cardiovascular: bulhas normofonéticas, ritmo cardíaco regular em 2T, aparelho respiratório: murmúrio vesicular fisiológico, ausência de ruídos adventícios; abdômen: plano, flácido, sem visceromegalias. Ao exame ginecológico, verificou-se genitália externa sem alterações e presença de pequena quantidade de sangramento. Considerando o caso descrito, assinale a alternativa que apresenta o procedimento que o médico DEVE realizar na emergência.","options":{"A":"Solicitar ultrassonografia transvaginal e fazer uma curetagem por aspiração para cessar o sangramento.","B":"Internar a paciente e solicitar o pré-operatório imediatamente.","C":"Prescrever estrógeno-progestogênio por via oral.","D":"Solicitar hemograma e ultrassonografia pélvica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234402","ankiGuid":"zH@?Zlm_SX"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-1650df7815d3231c","number":"0221h","sourceNumber":"0221h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Como conduzir de forma mais adequada sangramento uterino anormal em menina de 12 anos com exame físico e propedêutica complementar normais:","options":{"A":"associação oral de Ácido tranexâmico + AINH.","B":"ACHO combinado oral cíclico.","C":"Progesterona oral contínua de baixa dose.","D":"Progesterona oral na 2ª fase do ciclo.","E":"Expectante."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234403","ankiGuid":"IIPRt(B<Ya"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-25d945df3befbe7f","number":"0222h","sourceNumber":"0222h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Menina com 11 anos é trazida à emergência por sua mãe, por causa de sangramento vaginal abundante. O exame ginecológico não evidenciou lesões genitais, apenas o sangramento ativo; palidez cutânea, PA 90 X 40 mmHg, FC: 100 bpm, hemoglobina abaixo de 12g/dl; USG pélvica e coagulograma normais. Mediante o quadro clínico apresentado e resultado dos exames, qual a conduta mais adequada?","options":{"A":"Internação e reposição de volume.","B":"Internação e curetagem uterina.","C":"Internação, suporte básico de vida, prescrição de estrogênios orais em doses mais elevadas, e, vigilância constante da redução do sangramento vaginal.","D":"Tratamento ambulatorial com prescrição de anticoncepcional oral."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234404","ankiGuid":"dD-N3_[9E6"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-21fa72f5495f45ea","number":"0223h","sourceNumber":"0223h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente, 15 anos, vai ao consultório com queixa de sangramento vaginal aumentado mais dor tipo cólica. Paciente relata que, desde a menarca com 11 anos, apresenta ciclos irregulares com fluxos aumentados, utilizando absorventes noturnos, com duração de 10 dias. Nega relação sexual e também o uso de medicações. AP: nega cirurgias prévias, relata hemorragia, quando extraiu dente há 2 anos. AF: desconhece. Assinale a alternativa com a conduta correta para esse caso.","options":{"A":"Iniciar anticoncepcional oral somente com progestágenos.","B":"Aventar a possibilidade de sangramento uterino anormal e suspeitar de coagulopatia.","C":"Orientar a paciente de que essa fase é normal devido a ciclos anovulatórios.","D":"Pensar em síndrome dos ovários policísticos.","E":"Deve-se pedir uma videohisteroscopia para afastar causas endometriais."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234405","ankiGuid":"ceQS2O[4a0"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-8e97151474db4b39","number":"0224h","sourceNumber":"0224h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher de 66 anos comparece à consulta na UBS e relata estar em uso de metformina, glibenclamida, anlodipina e hidroclorotiazida há 10 anos. IMC 40,2Kg/m². Informa seis partos sem intercorrências e última menstruação aos 50 anos. Nega uso de terapia hormonal. Não realiza consultas médicas ou exames complementares há três anos. Informa episódios eventuais de sangramento vaginal leve com evolução progressiva nos últimos quatro meses. A conduta inicial MAIS ADEQUADA é solicitar:","options":{"A":"dosagem de FSH.","B":"histeroscopia diagnóstica.","C":"pan histerectomia total.","D":"ultrassonografia transvaginal."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234406","ankiGuid":"d+q#MhJ8sr"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-959bf46f5d9e2e89","number":"0225h","sourceNumber":"0225h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Sobre o sangramento uterino anormal está correto afirmar:","options":{"A":"Nas adolescentes os sangramentos por ciclos anovulatórios e defeitos na coagulação são mais frequentes que nas mulheres adultas.","B":"A biópsia de endométrio é uma propedêutica invasiva, por isso só está indicada em mulheres cujo tratamento inicial não teve o resultado esperado.","C":"Os pólipos endometriais podem ser causados por uso prolongado de métodos anticoncepcionais hormonais.","D":"A adenomiose é a causa mais comum de sangramento por aumento do volume uterino."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234407","ankiGuid":"Q(`j=q5iq0"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-6d97aaa41adb6efc","number":"0226h","sourceNumber":"0226h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente 40 anos, nuligesta, evolui com sangramento menstrual irregular há 6 meses. Traz beta-hCG negativo. Diante do exposto e considerando a classificação PALM-COEIN (FIGO,2011), que divide as causas de sangramento uterino anormal (SUA) em estruturais e não estruturais, qual alternativa CORRETA?","options":{"A":"Ultrassonografia é importante para avaliação inicial e se evidenciar um leiomioma subseroso pediculado de 2 cm, este será a provável etiologia do SUA.","B":"Nesta idade é muito frequente a incidência de câncer endometrial, logo a histeroscopia é exame inicial obrigatório para descartar tal patologia.","C":"Os pólipos, adenomiose, leiomiomas e malignidade são causas estruturais comuns de SUA e ultrassonografia pélvica é exame primordial na avaliação inicial.","D":"A dosagem hormonal inicial de FSH, estradiol, testosterona, TSH e prolactina é indispensável e deve ser realizado rotineiramente."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234408","ankiGuid":"uD=O/EKoC_"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-0d4015d53ba85ca8","number":"0227h","sourceNumber":"0227h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"A classificação PALM-COEIN, da Federação Internacional de Ginecologia e Obstetrícia (FIGO) para sangramentos uterinos, define como tratamento de primeira linha para, o sangramento uterino em mulheres de baixo risco para câncer de endométrio, com ultrassonografia normal, excluídas as causas estruturais e comorbidades, os","options":{"A":"progestágenos ciclícos.","B":"anticoncepcionais orais combinados.","C":"antifibrinolíticos, em especial o ácido tranexâmico.","D":"anti-inflamatórios, principalmente o ácido mefenâmico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234409","ankiGuid":"s,+#-_Atsu"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-6a1b7e12fa679958","number":"0228h","sourceNumber":"0228h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Algumas desordens ginecológicas, como a síndrome pré-menstrual, o mioma uterino e o sangramento uterino anormal, afetam milhares de mulheres, ocasionando transtornos emocionais, sintomatologia dolorosa e anemia. Entre essas desordens,","options":{"A":"a síndrome pré-menstrual é definida como cefaleia que se inicia na fase folicular do ciclo menstrual.","B":"o mioma uterino é o principal fator de sangramento uterino sem causa aparente (SUSCA).","C":"o sangramento uterino disfuncional (SUD) apresenta contraindicação de uso de anti- inflamatórios no tratamento.","D":"o sangramento uterino disfuncional (SUD) é o sangramento uterino relacionado com disfunção endócrina (insuficiência lútea ou anovulação)."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234410","ankiGuid":"N~&h<RF>3%"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-af5f062bfe6d4a07","number":"0229h","sourceNumber":"0229h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente 18 anos com 5 semanas de amenorreia deu entrada na maternidade referindo aparecimento de sangramento transvaginal de pequena monta após coito vaginal. A conduta inicial adequada para o caso:","options":{"A":"Exame especular.","B":"Orientação verbal sobre a possibilidade de laceração em fúrcula vaginal.","C":"Avaliação ultrassonográfica por via vaginal.","D":"Videocolposcopia.","E":"Uso de progesterona via vaginal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234411","ankiGuid":"fkta^rK);w"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-39468262a5b39623","number":"0230h","sourceNumber":"0230h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher, 55 anos, menopausa aos 50, vem ao ambulatório com queixa de sangramento genital em pequena quantidade, por dois dias, há uma semana. Nega terapia de reposição hormonal e traz ultrassom transvaginal que mostra útero medindo 100cm³, endométrio de 3mm e ovários não identificados. Diante desse caso clínico, qual a conduta mais adequada a seguir?","options":{"A":"Solicitar histeroscopia para afastar espessamento endometrial.","B":"Indicar biópsia endometrial para afastar câncer de endométrio.","C":"Realizar exame especular e toque vaginal para afastar lesões de colo e vagina.","D":"Inserir Sistema Intrauterino liberador de Levonorgestrel (SIU-LNG) para controlar sangramento."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234412","ankiGuid":"r`k,[@8/%E"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-fc8f1fdabbd6f231","number":"0231h","sourceNumber":"0231h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher, 25 anos, nuligesta, uso de condom como contraceptivo, nega comorbidades ou uso de medicações, procura atendimento com sangramento transvaginal intenso há mais de 15 dias. Apresenta nos antecedentes ginecológicos ciclos regulares com sangramento de fluxo progressivamente aumentado por 10 dias. Exame físico ginecológico sem alterações. Realizou B-HCG sanguíneo, cujo resultado foi negativo. Qual é a investigação inicial mais adequada para iniciar a propedêutica complementar da hemorragia uterina anormal?","options":{"A":"Solicitar hemograma completo, coagulograma e ultrassom transvaginal.","B":"Solicitar perfil hormonal completo para avaliar anovulação crônica.","C":"Orientar sobre a imaturidade do eixo hipotálamo-hipófise-ovário.","D":"Solicitar exames para diagnosticar as principais trombofilias."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234413","ankiGuid":"B2w>ik+mm&"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f838589ac9637d89","number":"0232h","sourceNumber":"0232h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 42 anos, GIII PIII A0, em uso de DIU de cobre há 8 anos. Comparece ao ambulatório de ginecologia geral queixando-se de sinusorragia há 8 meses, com aumento progressivo da frequência dos episódios. Nega uso de medicamentos e nega também desejo de ter mais filhos. A conduta mais adequada para essa paciente, neste momento é:","options":{"A":"Encaminhar a paciente para realização de laqueadura tubárea.","B":"Solicitar ultrassonografia transvaginal para avaliar posicionamento do DIU.","C":"Realizar exame especular e coleta de citologia oncótica do colo uterino.","D":"Orientar a paciente a realizar troca do DIU.","E":"Solicitar sorologias para investigação de doenças sexualmente transmissíveis."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234414","ankiGuid":"vhm^rfG/Vy"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-4581017ec9b1badc","number":"0233h","sourceNumber":"0233h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente 14 anos foi ao ginecologista referindo irregularidade menstrual. A menarca foi há 6 meses. Qual a hipótese diagnóstica mais provável?","options":{"A":"Pólipo","B":"Mioma","C":"Achado fisiológico","D":"Endometriose"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234415","ankiGuid":"fz]k4C+V{h"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-337d26c9bc56256f","number":"0234h","sourceNumber":"0234h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher climatérica, de 46 anos, com história de ciclos irregulares quanto aos intervalos, aumento do fluxo durante a menstruação, com dismenorreia secundária, apresenta à ultrassonografia mioma intramural, com maior diâmetro de 2,0 cm. Qual é o provável diagnóstico?","options":{"A":"Adenomiose.","B":"Endometríose.","C":"Anovulia.","D":"Mioma."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234416","ankiGuid":"i_S6FmcxV8"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-6e82b9ce61a2d240","number":"0235h","sourceNumber":"0235h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 38 anos, G3P3, relata aumento do fluxo menstrual e da duração da menstruação há oito meses. Nega uso de contraceptivos há um ano porque seu marido é vasectomizado. Seu último preventivo foi realizado em 04/2018 com laudo de negativo para malignidade. A MELHOR CONDUTA propedêutica inicial seria solicitar:","options":{"A":"Hemograma completo, prolactina, testosterona","B":"Hemograma completo, teste de gravidez, ultrassonografia transvaginal","C":"Hemograma completo, TSH, coagulograma","D":"Hemograma completo, ultrassonografia transvaginal, biópsia endometrial"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234417","ankiGuid":"z!{_X@L/|r"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-2e303675cfd07951","number":"0236h","sourceNumber":"0236h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Adolescente de 13 anos e 6 meses apresenta sangramento vaginal em grande quantidade com saída de coágulos há um dia. AP: menarca aos 12 anos, nega vida sexual ativa. Exame físico: PA 80 x 50 mmHg, descorada 3+/4, FC 110 bpm. A conduta inicial é","options":{"A":"solicitar hemograma e prescrever terapia estrogênica em altas doses com reavaliação em uma semana.","B":"internação, reposição volêmica, solicitar hemograma e teste de gravidez, se este negativo, prescrever terapia estrogênica em alta dose.","C":"internação, solicitar hemograma e iniciar reposição volêmica com cristaloides.","D":"observação, tranquilização da mãe e da paciente, suplementação vitamínica com ferro e reavaliação em uma semana."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234418","ankiGuid":"h{u={.d65G"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-b20d86e548a423b9","number":"0237h","sourceNumber":"0237h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Adolescente de 13 anos, virgem, com menarca aos 12 anos, deu entrada no serviço de emergência com sangramento transvaginal intenso. Fez ecografia pélvica que mostrou útero e anexos normais. Hematócrito 32% Hb 9 g%. Estudo da coagulação normal. Qual a conduta?","options":{"A":"Curetagem uterina de urgência","B":"Concentrado de hemácias + anti-inflamatório","C":"Estrogenioterapia em altas doses","D":"Iniciar anticoncepcional oral hormonal de imediato","E":"Nenhuma das anteriores"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234419","ankiGuid":"OWxe$5NcV7"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-95005d9eafd81639","number":"0238h","sourceNumber":"0238h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 13 anos, menarca há 2 meses, chega na emergência do Hospital com hemorragia há 2 dias. Ao exame: mucosas descoradas +++/4+, dispneica, hímen íntegro e saída de sangramento via vaginal em quantidade acentuada. βHCG negativo. Ao Ultrassom pélvico, útero e ovários normais para a idade. Não foi possível avaliar o endométrio devido a presença de coágulos intra-útero e por ser via suprapúbica. Qual a hipótese mais provável para este caso?","options":{"A":"Abortamento retido","B":"Distúrbio de coagulação","C":"Gestação molar","D":"Câncer do colo uterino"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234420","ankiGuid":"lu^QPpiak7"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-8da44b41966de4e6","number":"0239h","sourceNumber":"0239h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Uma mulher de 49 anos procura atendimento referindo hipermenorreia há 1 ano. Refere ciclos menstruais de 50 a 60 dias. Sem outras queixas. Realizou ultrassonografia transvaginal que demonstrou um útero com volume de 80 cm³, com superfície irregular e 3 nódulos hipoecogênicos subserosos, o maior deles medindo 1,5 cm × 1,1 cm nos seus maiores eixos, e endométrio com 0,6 cm de espessura. A causa mais provável da hipermenorreia é:","options":{"A":"Adenomiose.","B":"Miomatose uterina.","C":"Hiperplasia endometrial.","D":"Adenocarcinoma endometrial.","E":"Sangramento uterino disfuncional."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234421","ankiGuid":"Q;cZ,f+hao"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-62f33053142b6f42","number":"0240h","sourceNumber":"0240h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Joelma, 48 anos, com queixa de sangramento uterino aumentado há 6 meses, quando o intervalo entre as menstruações é irregular, variando entre 25 a 60 dias, nega uso de medicamentos ou comorbidades. Última colpocitologia oncológica do ano anterior normal. DUM há 15 dias; GII PII (partos vaginais). Exame físico: sem alterações significativas. Fez ultrassonografia transvaginal com útero em anteversoflexão, com dois miomas intramurais de 2,5 cm cada. Endométrio com 6 mm. Ovários não visualizados. Marque a opção compatível com a principal hipótese diagnóstica.","options":{"A":"Sangramento por adenomiose.","B":"Sangramento por leiomiomas.","C":"Sangramento por câncer de ovário.","D":"Sangramento por anovulação."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234422","ankiGuid":"yIwb?q`;s["},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-aad7b3fcf270b2ba","number":"0241h","sourceNumber":"0241h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Em pacientes adolescentes a causa mais comum de sangramento uterino anormal é:","options":{"A":"anovulação","B":"trauma genital","C":"doença inflamatória pélvica","D":"distúrbio de coagulação","E":"adenomiose"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234423","ankiGuid":"NU=|mdza_D"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-2cf44856838d43e0","number":"0242h","sourceNumber":"0242h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher 48 anos, sem comorbidades, procura atendimento médico com queixa de \"menstruação excessiva\". Refere que, há um ano, vem apresentando metrorragia intercalada com períodos de amenorreia. Ultrassonografia transvaginal recente, sem alterações. O tratamento indicado para controle do sangramento inclui o uso de:","options":{"A":"Estrogênio em doses crescentes entre o 5º e o 25° dia do ciclo.","B":"Tibolona entre o 5° e o 25° dia do ciclo.","C":"Progestágeno oral entre o 15° e o 25° dia do ciclo.","D":"Estrogênios entre o 15° e o 25° dia do ciclo."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234424","ankiGuid":"N1D+]wlP,Q"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-53670c11edae140e","number":"0243h","sourceNumber":"0243h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"O sangramento uterino anormal é uma queixa ginecológica comum que afeta mulheres em todas as idades. A menstruação cíclica regular requer relação perfeita entre o endométrio e seus fatores de regulação. Os fatores que mais influenciam na incidência são a idade e o estado reprodutivo. Com relação ao grupo populacional e à causa mais frequente do sangramento anormal, considere as afirmativas a seguir. I. Na idade reprodutiva, a principal causa está relacionada a tumores do trato genital, principalmente tumores ovarianos produtores de estrogênio. II. Na fase da adolescência, o sangramento anormal resulta, geralmente, de ciclos anovulatórios e de imaturidade do eixo hipotálamo-hipófise-ovário. III. Na perimenopausa, o sangramento é, geralmente, anovulatório e relacionado à disfunção do eixo hipotálamo-hipófise- ovário. IV. Na menopausa, a principal causa está relacionada à atrofia genital. Assinale a alternativa CORRETA.","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234425","ankiGuid":"v0s#LE9S!k"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-d74c2ee392008aa5","number":"0244h","sourceNumber":"0244h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 72 anos, menopausa aos 43 anos, G3P3, sem uso de terapia hormonal, procura o ginecologista por queixa de sangramento vaginal. Faz parte da propedêutica inicial:","options":{"A":"exame físico completo.","B":"exame especular.","C":"Exame cito-oncológico cervical.","D":"Ultrassonografia de endométrio.","E":"Todas as anteriores."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234426","ankiGuid":"v!hSk3%05Z"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-02ae60ec3bdfee34","number":"0245h","sourceNumber":"0245h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 19 anos, virgo, com queixa de sangramento uterino anormal (ciclos com intervalos regulares e fluxo aumentado), encontra-se há 7 meses em tratamento clínico (ácido tranexâmico, inibidores de prostaglandina e contraceptivos hormonais orais), porém sem melhora. Relata ciclos anteriores regulares. Realizou exames complementares: ultrassonografia pélvica normal, hemoglobina = 9,8 g/dl e hematócrito = 30%. O exame físico não detectou anormalidades. A conduta mais adequada para o caso é:","options":{"A":"Investigar distúrbios da coagulação.","B":"Fazer teste terapêutico com Análogo do GnRH.","C":"Induzir amenorreia com progesterona IM.","D":"Pesquisar outras doenças sistêmicas.","E":"Solicitar histeroscopia diagnóstica."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234427","ankiGuid":"er;FKsFc$b"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f678d9df6c294111","number":"0246h","sourceNumber":"0246h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher de 51 anos refere ciclos menstruais menorrágicos há 07 meses. Ciclos anteriores regulares. Traz FSH= 30,0 mUI/ml e TSH = 2,0 μUI/ml. Ultrassonografia transvaginal e mamografia foram normais. A conduta mais adequada para o caso é:","options":{"A":"Realizar avaliação clínica. Se normal, iniciar reposição hormonal com estrogênio e progesterona.","B":"Realizar exame físico e citologia cérvico-vaginal. Se normais, iniciar reposição hormonal com estrogênio e progesterona.","C":"Realizar exame físico, citologia cérvico-vaginal e avaliação clínica. Se normais, iniciar reposição com estrogênio e progesterona.","D":"Realizar exame físico, citologia cérvico-vaginal e avaliação clínica. Se normais, iniciar reposição com progesterona.","E":"Com a exclusão de causas orgânicas, indicar anti-inflamatórios não hormonais e/ou anti-fibrinolíticos."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234428","ankiGuid":"HpG%/4uGd)"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-c4e4cb30bc1b030c","number":"0247h","sourceNumber":"0247h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Qual a causa mais frequente de sangramento genital na paciente pré-púbere?","options":{"A":"Puberdade precoce.","B":"Vulvovaginites/ Corpo estranho.","C":"Agressão sexual.","D":"Câncer.","E":"Medicações contendo estrógenos."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234429","ankiGuid":"u7Y[1J,pkG"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-5843b7fb3ddefcc7","number":"0248h","sourceNumber":"0248h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Na urgência, a alternativa de tratamento em sangramento uterino anormal com menor chance de sucesso é","options":{"A":"estrogênios conjugados 2,5 mg VO de 6/6 horas até diminuir o sagramento.","B":"anticoncepcional oral combinado.","C":"ácido tranexâmico.","D":"minipílua.","E":"curetagem uterina."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234430","ankiGuid":"h`W$r@lnYB"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-68a9c19d3fd6d49a","number":"0249h","sourceNumber":"0249h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"O Sangramento Uterino Anormal (SUA) tem como definição a perda menstrual excessiva, com repercussões físicas, emocionais, sociais e materiais na qualidade de vida da mulher. É condição que afeta até 40% das mulheres em todo mundo, impactando de forma negativa a vida dessa população. Em relação ao tratamento do SUA, são escolhas de alta eficácia:","options":{"A":"Análogos de GnRH e anti-inflamatórios não esteroidais.","B":"SIU-LNG (Sistema uterino de levonorgestrel) e anti-inflamatórios não esteroidais.","C":"Contraceptivos orais combinados e ácido tranexâmico.","D":"Acetato de medroxiprogesterona de depósito e ácido tranexâmico."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234431","ankiGuid":"nYK3+W-.vY"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-ca86219698a33b86","number":"0250h","sourceNumber":"0250h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente 18 anos, G0 P0, histórico de ciclos menstruais regulares, sem cólicas, e com duração do fluxo de cinco dias, sendo mais intenso nos três primeiros dias do ciclo e em pequena quantidade nos últimos dois dias. Procurou a emergência, acompanhada pelo namorado. Refere que iniciou quadro de hemorragia genital intensa e súbita, há 3 horas, associado a palidez de mucosas, hipotensão arterial e astenia. Relatou estar no 8º dia do ciclo menstrual e que o sangramento iniciou logo após o coito, nega uso prévio de mediações e refere boa saúde. Utiliza condon como método contraceptivo. Neste caso a conduta a ser tomada é","options":{"A":"exame especular.","B":"teste de Gravidez.","C":"ultrassonografia.","D":"exames hormonais (FSH, LH, Estradiol, Prolactina, T SH)."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234432","ankiGuid":"zFZu}p:(}D"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-564382a9e4b030f0","number":"0251h","sourceNumber":"0251h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente 18 anos, G0 P0, histórico de ciclos menstruais regulares, sem cólicas, e com duração do fluxo de cinco dias, sendo mais intenso nos três primeiros dias do ciclo e em pequena quantidade nos últimos dois dias. Procurou a emergência, acompanhada pelo namorado. Refere que iniciou quadro de hemorragia genital intensa e súbita, há 3 horas, associado a palidez de mucosas, hipotensão arterial e astenia. Relatou estar no 8º dia do ciclo menstrual e que o sangramento iniciou logo após o coito, nega uso prévio de mediações e refere boa saúde. Utiliza condon como método contraceptivo. Neste caso a hipótese diagnóstica é","options":{"A":"laceração de fundo de saco vaginal.","B":"abortamento em curso.","C":"sangramento uterino disfuncional.","D":"miomatose uterina."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234433","ankiGuid":"c1afT*e[0%"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-28ba2892e1a2e93b","number":"0252h","sourceNumber":"0252h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Analise as opções a seguir e assinale a CORRETA.","options":{"A":"Metrorragia: sangramento uterino irregular.","B":"Menometrorragia: menstruação prolongada e abundante com sangramento não rítmico, irregular.","C":"Polimenorréia: menstruação com intervalo inferior a 21 dias.","D":"Menorragia: menstruação prolongada (> 7 dias ou abundante > 80 mL).","E":"Todas as afirmativas estão corretas."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234434","ankiGuid":"I)&{Ha4Gvj"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-77fd960004d14c2e","number":"0253h","sourceNumber":"0253h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Adolescente 13 anos apresenta ciclo menstrual com intervalos irregulares, com duração e fluxos excessivos. A hipótese mais provável para as alterações menstruais na adolescente é:","options":{"A":"presença de tumores ovarianos.","B":"imaturidade do eixo hipotálamo-hipofisário.","C":"ocorrência de coagulopatias.","D":"uso de fármacos."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234435","ankiGuid":"sD{TT?U[6B"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f4b40ceb9e902031","number":"0254h","sourceNumber":"0254h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Qual a causa mais frequente de sangramento genital na pós menopausa, sem terapia hormonal?","options":{"A":"Atrofia de endométrio.","B":"Câncer de endométrio.","C":"Pólipo endometrial.","D":"Neoplasia ovariana.","E":"Mioma submucoso."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234436","ankiGuid":"I&S{O8bc[y"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-fb8e7fd014f1d682","number":"0255h","sourceNumber":"0255h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Uma adolescente, que começou a apresentar ciclos menstruais aos 13 anos, hoje os apresenta menores que 21 dias e com o período menstrual maior que 8 dias. Esses eventos são, respectiva e corretamente, denonimados:","options":{"A":"espaniomenorreia e metrorragia","B":"polimenorragia e metrorreia","C":"polimenorreia e hipermenorreia","D":"menorragia e espaniomenorreia","E":"opsomenorreia e hipermenorragia"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234437","ankiGuid":"l5%,|g{=pQ"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-8c5f7a0d3ff17b74","number":"0256h","sourceNumber":"0256h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 70 anos de idade, GI P0 AI, menopausa aos 50 anos, obesa, hipertensa, apresenta sangramento vaginal que iniciou há 2 meses. Nega uso de terapia hormonal. Traz consigo ultrassonografia transvaginal realizada há 1 mês que evidenciou um endométrio de 10 mm. O exame ginecológico não mostrou lesão em vagina e colo. A propedêutica mais eficaz para a investigação do sangramento é:","options":{"A":"Colpocitologia oncótica.","B":"Curetagem uterina.","C":"Histeroscopia.","D":"Não há necessidade de investigação do sangramento, pois a paciente já realizou a ultrassonografia transvaginal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234438","ankiGuid":"kdao?B|^NY"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-a3b491420d3022f9","number":"0257h","sourceNumber":"0257h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 65 anos, menopausada há 10 anos, procura o ambulatório de ginecologia queixando-se de sangramento vaginal há um mês. É obesa, diabética e hipertensa não bem controlada. Ao exame colo uterino de aspecto normal, ausência de sangramentos, útero e anexos impalpáveis ao toque. Qual a melhor conduta?","options":{"A":"Histerectomia subtotal.","B":"Histerectomia com anexectomia.","C":"Conização com pontos de Stumdorf.","D":"Histeroscopia com biópsia de endométrio.","E":"Histerossalpingografia com contraste iodado."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234439","ankiGuid":"kKf<wquYlC"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-2c0619714c358695","number":"0258h","sourceNumber":"0258h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher menopausada há 10 anos, sem fazer uso de nenhuma medicação hormonal, apresentou história de que, por três vezes, teve sangramento vaginal no último mês. Procurou o ambulatório de ginecologia. Qual é o diagnóstico mais provável?","options":{"A":"Carcinoma de endométrio.","B":"Hiperplasia endometrial.","C":"Atrofia endometrial.","D":"Pólipo endometrial.","E":"Discrasia sanguínea."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234440","ankiGuid":"mw[zY^KOh|"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-ebf71a49e753ce87","number":"0259h","sourceNumber":"0259h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Uma mulher de 37 anos, negra, nulípara, procura a UBS com queixa de sangramento vaginal irregular, durando quase todo o mês; está assim há seis meses e vem piorando. Ao exame ginecológico, o médico identifica que o útero está aumentado de volume. Frente a esse quadro, qual exame de imagem deve ser realizado e o que se espera dele?","options":{"A":"Ultrassonografia pélvica para avaliar a espessura endometrial, pois há grande possibilidade de se tratar de hiperplasia ou carcinoma endometrial.","B":"Histerossalpingografia para investigar a existência de pólipo endometrial, que é um fator que justifica a metrorragia.","C":"Ultrassonografia pélvica para identificar e assim confirmar a hipótese mais provável de mioma subseroso.","D":"Ressonância nuclear magnética, que é o exame “padrão-ouro” e que melhor identifica e localiza nódulos de mioma.","E":"Ultrassonografia pélvica para avaliar a presença de mioma submucoso, que é a localização que mais justifica esse padrão de sangramento."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234441","ankiGuid":"pcVt1,r;D_"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f70b94397bf91a8b","number":"0260h","sourceNumber":"0260h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Uma paciente de 41 anos de idade procurou o PS com queixa de sangramento vaginal de moderada intensidade, com a saída de coágulos, há três horas. Refere irregularidade menstrual com piora progressiva nos últimos seis meses e ser laqueada. Nega doenças, uso de medicações e tabagismo. Ao exame físico, apresentava-se descorada e com PA de 120 x 80 mmHg. O exame abdominal não mostrou alterações. Ao exame especular, observou-se presença de coágulos na vagina, com a saída de sangue pelo orifício externo do colo uterino, e, ao toque, útero em anteversoflexão, com tamanho normal e regiões anexiais livres. Com base nesse caso hipotético, é CORRETO afirmar que o diagnóstico e a melhor conduta, considerando-se a eficácia e a segurança, sejam, respectivamente:","options":{"A":"Sangramento uterino anormal e progestógeno ou estrogênio com progestógenos emaltas doses.","B":"Sangramento uterino secundário à coagulopatia e ácido tranexâmico.","C":"Sangramento uterino de causa estrutural (adenomiose) e anti-inflamatório.","D":"Sangramento uterino de causa ovulatória (transição menopausal) e reposição hormonal com baixa dosagem de estradiol e progestógeno.","E":"Sangramento uterino de causa iatrogênica e embolização das artérias uterinas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234442","ankiGuid":"vAZb~N&RrZ"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-10c9b0f566153bcf","number":"0261h","sourceNumber":"0261h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher de 72 anos de idade, 4G 4P, sem comorbidades, refere apresentar pequeno sangramento pela vagina, há uma semana. Ao exame físico, vagina, colo do útero e corpo uterino estão normais para a idade. O diagnóstico mais provável é de:","options":{"A":"Hiperplasia endometrial típica.","B":"Atrofia endometrial.","C":"Hiperplasia endometrial com atipia.","D":"Carcinoma endometrial.","E":"Pólipo endometrial."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234443","ankiGuid":"n9)_6{[5M!"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f24d12b9c983894a","number":"0262h","sourceNumber":"0262h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Em relação à hemorragia que acontece no meio do ciclo menstrual, assinale a afirmação CORRETA.","options":{"A":"Necessita tratamento pelo risco de formação de neoplasia.","B":"Pode ser tratada com anticoncepcionais orais.","C":"A principal causa é hiperplasia endometrial.","D":"A causa básica geralmente é o pólipo endometrial."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234444","ankiGuid":"k/2!0{$3tm"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-b9d2ef486016d637","number":"0263h","sourceNumber":"0263h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente 25 anos, chega a consulta com queixa de sangramento vaginal moderado há 3 dias, com discreta quantidade de coágulos e dor abdominal tipo cólica de moderada intensidade. Ao exame apresenta abdome plano flácido pouco doloroso à palpação profunda em hipogástrio, sem visceromegalias, ruídos hidroaéreos presentes. Ao exame especular não se observou anormalidades. Ao toque vaginal bimanual apresentou útero de volume habitual, colo uterino impérvio, sem dor à mobilização do colo e anexos impalpáveis. Exame betahcg não reagente. Das opções listadas abaixo, são alternativas para o controle do sangramento uterino anormal, EXCETO:","options":{"A":"Fitomenadiona 10mg (vitamina K1) 1 amp IM profunda","B":"Etinilestradiol 0,03mg + Levonorgestrel 0,25mg 1cp via oral 2 a 3 vezes ao dia, pausa para iniciar o sangramento de privação, passando a uma vez por dia durante 3 ciclos.","C":"Ácido Tranexâmico 1g via oral 3 a 4 vezes ao dia, durante o sangramento (3 a 4 dias)","D":"Norestiterona 15mg via oral por dia, durante 3 semanas. A dose é reduzida quando o sangramento parar, normalmente em 1 semana. Se não cessar, aumentar a dose."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234445","ankiGuid":"lHf{Mf1(Ru"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-6bd1a968e213d83d","number":"0264h","sourceNumber":"0264h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente com 51 anos, em menopausa há dois anos. Há um mês teve episódio de dor pélvica moderada, isolada. Sem cirurgias prévias ou sangramento vaginal pós- menopausa. Ultrassonografia (USG) transvaginal: útero de dimensões normais, ovários não visualizados e espessura endometrial de três milímetros. A conduta mais adequada é:","options":{"A":"Realizar biópsia endometrial.","B":"Observar, sem programar exames ou intervenções.","C":"Programar histeroscopia com biópsia, se visualizada atrofia endometrial.","D":"Realizar histerossonografia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234446","ankiGuid":"g@g*v#g-2h"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f953998d1dc5db33","number":"0265h","sourceNumber":"0265h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Myrna, 59 anos, refere sangramento uterino (episódio único e em pouca quantidade) há três semanas. Menopausa: 49 anos. G3 P3 A0. Exame clínico-ginecológico normal, exceto pela atrofia vulvovaginal. IMC: 23 kg/m². PA: 110 x 70 mmHg. A conduta inicial é:","options":{"A":"Histeroscopia.","B":"Teste da progesterona.","C":"Ultrassonografia transvaginal.","D":"Teste do estrogênio e progesterona.","E":"Ressonância da pelve."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234447","ankiGuid":"DnS.-qJQ<"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-23d54b4ab5254f49","number":"0266h","sourceNumber":"0266h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher de 48 anos, refere sangramento uterino anormal há 8 meses, quando percebeu que seu fluxo menstrual aumentou de duração, passando de quatro para oito dias, e de volume, apresentando atualmente perda de coágulos. O intervalos entre as menstuações é irregular, variando entre 20 e 55 dias. Nega uso de medicamentos ou comorbidades. Última colpocitologia oncológica do ano anterior normal. DUM há 15 dias; GII PII (partos vaginais). Exame físico: hipocorada +/+4; IMC=27 Kg/m²; exame abdominal, vulvar, vaginal, do colo e útero, normais. Fez ultrassonografia transvaginal com útero em anteversoflexão, com dois miomas intramurais de 2 e 1,5 cm cada. Endométrio com 8 mm. Ovários não visualizados. Qual a principal hipótese diagnóstica?","options":{"A":"Sangramento por hiperplasia endometrial.","B":"Sangramento por leiomiomas.","C":"Sangramento por câncer de endométrio.","D":"Sangramento por anovulação."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234448","ankiGuid":"z0n1whLZ$c"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-70d683870d1dfa53","number":"0267h","sourceNumber":"0267h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher de 47 anos de idade deu entrada na emergência com queixa de menorragia há mais de sete dias e ciclos menstruais irregulares no último ano. Referiu menarca aos 12 anos, G3P3 (três cesarianas) e realizou ligadura tubária no momento da cesariana do último filho. Ao exame apresentava-se hipocorada +++/+4, PA 80x50 mmHg, frequência cardiaca de 118 bpm, abdome e pelve sem massas palpáveis, colo regular e presença de sangramento uterino moderado ao exame especular. Realizou hemograma (hematócrito de 18%, hemoglobina de 6,7g/dL, 220.000 plaquetas) e ultrassonografia transvaginal que não apresentou alterações. A conduta médica recomendada nesse caso é:","options":{"A":"hospitalização, hemotransfusão e estrogenioterapia","B":"hospitalização, hidratação venosa com cristaloide e ácido tranexânico via oral","C":"manejo ambulatorial com reposição de sulfato ferroso e contraceptivo oral combinado de alta dose","D":"manejo ambulatorial com anti-inflamatótio não esteroide após a hemotransfusão"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234449","ankiGuid":"Q{eSX4HAtY"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-2359ddc6608a1a69","number":"0268h","sourceNumber":"0268h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Sangramentos vaginais são aqueles de origem ginecológica e que se exteriorizam pela vulva, excetuando-se, desse modo, aqueles de origem obstétrica. Com relação ao sangramento vaginal é correto afirmar que:","options":{"A":"As causas de sangramento genital são os mesmos durante todas as fases da vida da mulher.","B":"O uso de maleato de metilergometrina é parte do protocolo em sangramentos não associados ao puerpério, sendo de primeira escolha, pois atua no musculo liso do útero diminuindo o tônus basal.","C":"Sangramento genital pode originar-se na vagina, cérvice ou útero, por isso é necessário exame ginecológico.","D":"Nos sangramentos vaginais é indicado o uso de acido tranexâmico por tempo superior a 7 dias pois atua prevenindo trombose venosa."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234450","ankiGuid":"s7zxb,ZL&;"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-0080c9c51f4111f5","number":"0269h","sourceNumber":"0269h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 25 anos, virgo, vem ao consultório referindo ciclos menorrágicos há 04 meses. Sem outras queixas. Ciclos anteriores regulares. Nega uso de medicamentos de qualquer natureza. IMC=22. Exame físico geral e ginecológico normais. Assinale a opção CORRETA.","options":{"A":"Solicitar hemograma, US Pélvico, TSH e investigar distúrbios de coagulação.","B":"Iniciar teste terapêutico com medicação hormonal. Havendo resposta, o diagnóstico é o sangramento uterino disfuncional.","C":"Os dados: ciclos anteriores regulares, exame físico normal, IMC normal e o padrão do sangramento (menorragia) caracterizam sangramento disfuncional ovulatório. Portanto, iniciar tratamento com ácido tranexâmico e/ou anti- inflamatório não hormonal.","D":"Se os exames, US Pélvico e TSH, estiverem normais, iniciar tratamento clínico para sangramento uterino anormal.","E":"Interrogar se existem sintomas pré-menstruais como mastalgia e dismenorreia. Se ausentes, caracterizar como sangramento disfuncional anovulatório e iniciar tratamento hormonal."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234451","ankiGuid":"Gdqz;^RQF~"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-41b7515b6e477869","number":"0270h","sourceNumber":"0270h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente feminina, 40 anos de idade, chega ao pronto-socorro com queixa traduzida por hipermenorreia. Tem sinais clínicos de anemia. Já possui diagnóstico firmado de sangramento uterino disfuncional, por especialista na área. Assinale a alternativa que apresenta, corretamente, a melhor conduta nesse caso.","options":{"A":"Estrogênios via oral em alta dose.","B":"Histeroscopia.","C":"Infundir plasma fresco.","D":"Expectante, com repouso e tranquilização da paciente.","E":"Ultrassonografia pélvica endovaginal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234452","ankiGuid":"B&<UIkt;*:"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-6f0d47af555331f6","number":"0271h","sourceNumber":"0271h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Adolescente, 12ᵃ, procurou consulta médica por estar menstruando a cada 40 a 50 dias, com fluxo de duração de 9 dias. Nos 4 primeiros dias elimina coágulos e necessita de 9 absorventes por dia. Antecedente pessoal: menarca há 15 meses. Nega atividade sexual. Exame físico: descorada 2+/4+, hímen integro, com saída de coágulos ao esforço (tosse). O diagnóstico é","options":{"A":"Doença de Von Willebrand","B":"Sangramento uterino disfuncional","C":"Púrpura trombocitopênica idiopática","D":"Pólipo endometrial."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234453","ankiGuid":"fAk]h*+DYH"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-92ed342ff5d4a13d","number":"0272h","sourceNumber":"0272h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Em relação aos métodos diagnósticos nos sangramentos genitais, marques a alternativa CORRETA:","options":{"A":"A ultrassonografia estuda o endométrio, o miométrio, os ovários, pode ser realizada em todas as faixas etárias e é a primeira linha diagnóstica na identificação de anormalidades estruturais.","B":"A citologia endometrial, pela alta sensibilidade para doenças benignas, é recomendada como recurso de primeira linha na avaliação do sangramento uterino anormal.","C":"A biópsia endometrial com a cureta de Novak é considerada uma técnica simples, de fácil interpretação e um teste com alta sensibilidade para o diagnóstico de câncer endometrial.","D":"A curetagem com dilatação é o método mais utilizado na investigação da cavidade endometrial devido a alta acurácia no diagnóstico de hiperplasia e câncer, de 79.1% e 90.2% respectivamente."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234454","ankiGuid":"y?b`u!yqz?"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f52ac1d5c1626ce1","number":"0273h","sourceNumber":"0273h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 13 anos, menarca há 6 meses, admitida no pronto atendimento com história de sangramento menstrual excessivo há 5 dias. Nega atividade sexual, mas a entrevista foi realizada na presença da mãe. Solicitado eritrograma na urgência que mostrou hemoglobina de 8,5g% e hematócrito de 22%. Teste de gravidez negativo. PA de 80x40mmHg e pulso de 120bpm. Assinale a alternativa que apresenta o diagnóstico MAIS provável.","options":{"A":"Deficiência de fator VIII.","B":"Anovulação.","C":"Uso inadequado de pílula.","D":"Abuso sexual."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234455","ankiGuid":"KI})%jos?q"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-5ff78d90710b1a4f","number":"0274h","sourceNumber":"0274h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"A Federação Internacional de Ginecologia e Obstetrícia (FIGO) indicou o Sistema PALM-COEIN para sistematizar a investigação de qual problema ginecológico?","options":{"A":"Endometriose.","B":"Amenorreia.","C":"Infertilidade.","D":"Câncer de colo de útero.","E":"Sangramento uterino anormal."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234456","ankiGuid":"g:|d6,qsd&"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-249fa1ea55b86c32","number":"0275h","sourceNumber":"0275h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Sangramento uterino anormal no menacme, com perda da ciclicidade, associado a períodos de amenorreia, com FSH, TSH e prolactina normais, sem prole definida, tem como primeira opção terapêutica","options":{"A":"a ablação de endométrio.","B":"os anti-inflamatórios não hormonais.","C":"os antifibrinolíticos.","D":"os anticoncepcionais hormonais."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234457","ankiGuid":"QD7bsFZ`v>"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-08af3923f597e75c","number":"0276h","sourceNumber":"0276h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 42 anos procura a emergência de atendimento ginecológico por apresentar sangramento uterino intenso no período menstrual, dismenorreia intensa agravada no último ano e dispareunia, que torna a atividade sexual um grande sofrimento pela dor. O grupo em que essa doença pode ser considerada pela classificação PALM-COEIM, de acordo com a FIGO, o diagnóstico e a alteração uterina que pode ser encontrada no exame de toque vaginal são, respectivamente:","options":{"A":"grupo de PALM, diagnóstico de leiomioma, útero de consistência amolecida.","B":"grupo de PALM, diagnóstico de adenomiose, útero doloroso e superfície lisa.","C":"grupo de COEIM, diagnóstico de endometriose, útero doloroso.","D":"grupo de COEIM, diagnóstico de câncer de endométrio avançado, útero de tamanho normal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234458","ankiGuid":"z*-<kUhP^s"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-1a79bf3cef1da2f6","number":"0277h","sourceNumber":"0277h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"P.N.M., 13 anos, apresenta ciclos menstruais regulares de 28 dias desde a primeira menstruação, aos 11 anos. No último mês, necessitou procurar o pronto atendimento por sangramento vaginal em grande quantidade, inclusive necessitando de transfusão sanguínea. No exame físico atual, apresenta mucosas descoradas 2+/4, sem outras alterações relevantes. Qual é a conduta mais adequada para esse caso?","options":{"A":"Tranquilizar a paciente, pois mais de 80% dos casos de sangramento anormal nessa fase da vida da mulher ocorre devido à imaturidade do eixo hipotálamo-hipófise ovariano.","B":"Realizar calendário menstrual e prescrição de antifibrinolíticos ou anti-inflamatórios.","C":"Avaliação do hematologista, pois é possível que a paciente apresente algum distúrbio da hemostasia.","D":"Realizar perfil androgênico (17 OH progesterona, testosterona total, DHEAS) e ultrassonografia transvaginal para afastar a presença de síndrome dos ovários policísticos.","E":"Como o ciclo é regular, prescrever estrogênios para contenção do sangramento na fase aguda."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234459","ankiGuid":"E]*:]=@Q3I"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-4ffff640d5a45892","number":"0278h","sourceNumber":"0278h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher de 40 anos refere sangramentos menstruais excessivos nos últimos 5 ciclos, que se apresentam com intervalo de 30 dias, duração de 7 dias e perda de coágulos. Nega comorbidades, uso de medicamentos, cirurgias prévias e alergias. Antecedente de 2 partos vaginais, último há 10 anos. Marido vasectomizado. No momento, o sangramento é intenso, terceiro dia do ciclo. Ao exame clínico: FC = 90 bpm; PA = 120 x 80 mmHg; abdome flácido indolor. Exame especular: colo epitelizado e grande quantidade de sangue na vagina com exteriorização pelo canal cervical. Exame pélvico com útero em anteversoflexão, não doloroso, tamanho normal e regiões anexiais livres. Neste momento, a medicação mais adequada para o controle do sangramento é:","options":{"A":"Dehidroepiandrosterona (DHEA).","B":"Diclofenaco sódico.","C":"Progesterona.","D":"Ácido tranexâmico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234460","ankiGuid":"wHDab33.pi"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f43050113511b2c7","number":"0279h","sourceNumber":"0279h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Em relação ao sangramento uterino disfuncional, analise as assertivas a seguir: I – É característico de ciclos anovulatórios, sendo muito comum logo após a menarca e na perimenopausa; II – Pólipo endometrial e miomatose uterina são causas comuns; III – Os anticoncepcionais combinados orais e os antifibrinolíticos são opções terapêuticas. Está/estão CORRETA (S):","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"I, II e III."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234461","ankiGuid":"z&aUG/|4$X"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-f4f1ad00c2c993ea","number":"0280h","sourceNumber":"0280h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Em relação à irregularidade menstrual, analise as assertivas a seguir: I – Na presença de irregularidade menstrual em mulher sexualmente ativa, é necessário descartar gravidez; II – Nos dois primeiros anos pós-menarca, a irregularidade menstrual pode ser fisiológica, por imaturidade do eixo hipotálamo-hipófise-ovário; III – Na perimenopausa, é comum irregularidade menstrual por anovulação; IV – Na irregularidade pós-menarca, a causa patológica mais comum é a síndrome dos ovários policísticos.","options":{"A":"Apenas I e II.","B":"Apenas III e IV.","C":"Apenas I, II e III.","D":"Apenas II, III e IV.","E":"I, II, III e IV."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234462","ankiGuid":"ox$DlzC^4"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-71fd376d0c8a125f","number":"0281h","sourceNumber":"0281h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 25 anos em uso de Anticoncepcional Combinado Oral (ACO), com 20 mcg de etinilestradiol há 1 ano apresenta sangramento intermenstrual (spotting) há 60 dias. Nega doenças crônicas ou uso de outros medicamentos. Refere que, às vezes, esquece de tomar o ACO e que tem parceiro sexual único. Além do exame ginecológico, qual a conduta imediata mais adequada?","options":{"A":"Realizar ultrassonografia transvaginal para avaliar a cavidade uterina.","B":"Solicitar B-HCG para descartar gravidez.","C":"Trocar o ACO para um com dose de 30 mcg de etinilestradiol.","D":"Prescrever antibioticoterapia para tratar endometrite.","E":"Suspender o ACO e indicar DIU medicado com levonorgestrel."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234463","ankiGuid":"gW-g/WSMeR"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-c429baa343939c77","number":"0282h","sourceNumber":"0282h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher, 47 anos, atendida com sangramento transvaginal intenso há cinco dias. Relata que nos últimos 18 meses o fluxo menstrual está irregular com intervalo variando entre 20 e 50 dias e o fluxo está intenso neste mesmo período. Gesta 2 Para 2 (partos cesáreos) e laqueadura tubária há 15 anos. Vida sexual ativa, parceiro fixo, não faz uso de condom. Nega uso regular de medicamentos. Não é atendida por nenhum médico há cinco anos. Exame Físico: sinais vitais normais, sem sinais de hipovolemia. Exame pélvico normal, útero intrapélvico, móvel e indolor. Colo do útero normal com sangue saindo pelo orifício externo do canal endocervical. Retorna após 7 dias, trazendo exames realizados e solicitados pelo médico assistente. Ultrassonografia transvaginal: útero AVF, medindo 78 x 65 x 59 mm, endométrio com 13 mm, nódulo uterino medindo 3 cm, subseroso; ovário direito não identificado; ovário esquerdo com cisto anecoico medindo 19 x 13 mm. Colpocitologia Oncótica: amostra satisfatória, epitéliosescamoso e metaplásico, processo inflamatório inespecífico, negativo para neoplasia. A hipótese diagnóstica, mais provável, do sangramento uterino anormal é","options":{"A":"Leiomiomatose uterina.","B":"Disfunção ovulatória.","C":"Endometrioma ovariano.","D":"Doença inflamatória pélvica aguda.","E":"Lesão pré-maligna do colo uterino."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234464","ankiGuid":"lk^hT`?/p>"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-daef6a0260e3dd36","number":"0283h","sourceNumber":"0283h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"O primeiro exame a ser solicitado para uma paciente com sangramento uterino anormal no menacme deve ser:","options":{"A":"Hemograma completo.","B":"TSH e T4 livre sérico.","C":"Beta HCG sérico.","D":"Coagulograma."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234465","ankiGuid":"cEXo}6(>;w"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-be5e4285d3bbeefb","number":"0284h","sourceNumber":"0284h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"A conduta no sangramento pós-menopausa com ultrassonografia pélvica normal é:","options":{"A":"administração de progestogênio.","B":"administração de estrogênio.","C":"administração de estrogênio e progestogênio.","D":"histeroscopia com biópsia endometrial."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234466","ankiGuid":"h)j+q3xF`I"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-6e3026763682da79","number":"0285h","sourceNumber":"0285h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente com 31 anos de idade procura pronto-atendimento de ginecologia relatando fluxo menstrual abundante, com duração de 6 a 7 dias em cada ciclo, tendo iniciado há 9 meses, ciclos menstruais irregulares (intervalo de 38 a 40 dias). Gesta 2 Cesárea 2. No momento, paciente com sangramento via vaginal intenso. Tem histórico de laqueadura tubária. Pressão arterial 100 x 60 mmHg. Frequência cardíaca 110 batimentos por minuto. No histórico médico pessoal, refere uso de levotiroxina 75 mcg/dia. Vem com os seguintes exames: TSH 2,8 mU/L. Hemoglobina 5,9 g/dL. Hematócrito 21%. Plaquetas normais. Ecografia pélvica endovaginal: volume uterino 130 cm³. Endométrio 10 mm, ovários com volumes normais. Com base no exposto, qual a melhor conduta?","options":{"A":"Desogestrel 75 mcg/dia + indicar histeroscopia.","B":"Piroxicam 20 mg/dia + ringer lactato.","C":"Acetato de gosserrelina 10,8 mg subcutânea + hemotransfusão.","D":"Hemotransfusão + ácido tranexâmico 1 ampola endovenosa (250 mg) lentamente a cada 8 horas.","E":"Hemotransfusão + pílula contendo etinilestradiol 20 mcg + desogestrel 150 mcg sendo uma pílula por dia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234467","ankiGuid":"nry+?P!kas"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-dc9127cb628de0b7","number":"0286h","sourceNumber":"0286h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"De acordo com o guia prático da FEBRASGO 2014/2015 intitulado Tratamento do sangramento uterino anormal (Menorragia) existe uma terminologia universal para as variações do sangramento uterino anormal, segundo esta terminologia denomina-se polimenorreia:","options":{"A":"sangramento uterino prolongado, acima de oito dias, ou de quantidade excessiva, maior que 80 ml, ou a associação de ambos.","B":"ciclos menstruais que ocorrem com intervalos acima de 35 dias.","C":"ciclos menstruais cuja frequência é inferior a 24 dias.","D":"sangramento uterino que ocorre fora do período menstrual.","E":"sangramento que ocorre durante o período menstrual e fora dele."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234468","ankiGuid":"q-?#ohxlb<"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-052ee5b76a8e1145","number":"0287h","sourceNumber":"0287h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Com relação ao sangramento uterino disfuncional na idade reprodutiva da mullher, assinale a alternativa ERRADA:","options":{"A":"Na maioria dos casos, o sangramento uterino disfuncional é ovulatório e causado por supressão estrogênica","B":"Na prática médica rotineira, a expressão ''Sangramento Uterino Disfuncional'' é utilizado como diagnóstico de exclusão e não como um sintoma","C":"Nos quadros de hemoragia uterina disfuncional a cicatrização do endométrio é assincrônica e irregular","D":"Nos quadros de Hemorragia uterina disfuncional os níveis maiores de estrogênios causam episódios de amenorreia seguidos de hemorragia aguda"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234469","ankiGuid":"BSfRhe}qfh"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-8c3652c27213db2b","number":"0288h","sourceNumber":"0288h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"APJ, 16 anos, feminina, com queixa de hipermenorreia, com anemia ferropriva. Ultrassonografia endovaginal mostrou útero e anexos normais. Ao exame especular, vagina e colo uterino normais, sendo classificado como sangramento disfuncional. Observe as afirmativas abaixo e assinale a incorreta.","options":{"A":"Sangramento disfuncional uterino é considerado quando observa-se um sangramento em grande quantidade, e não usa-se este termo quando a frequência e a duração são maiores que o considerado normal.","B":"Alterações endócrinas como obesidade, magreza excessiva ou síndrome de Cushing podem ser causa de sangramento uterino disfuncional.","C":"Distúrbios de coagulação sanguínea podem ser causa de sangramento uterino disfuncional.","D":"Em adolescentes o sangramento uterino disfuncional pode ser limitado, sendo importante observar antes de realizar intervenção medicamentosa.","E":"Quando há sinal de hipovolemia em paciente jovem, o uso de estrogênio em altas doses está indicado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234470","ankiGuid":"b]T5Dp)1/h"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-c9077530021cbdbf","number":"0289h","sourceNumber":"0289h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher 19 anos, nuligesta, procura a UBS pois refere que seus ciclos estão irregulares e o número de dias de sangramento está aumentando. Você pediu um calendário menstrual e 6 meses mais tarde, ela traz o calendário para a sua avaliação. Abaixo, estão listadas a duração de cada ciclo e do sangramento. 1° ciclo: 36 dias - 7 dias de sangramento. 2° ciclo: 26 dias - 5 dias de sangramento. 3° ciclo: 33 dias - 6 dias de sangramento. 4° ciclo: 30 dias - 8 dias de sangramento. 5° ciclo: 24 dias - 5 dias de sangramento. 6° ciclo: 34 dias - 8 dias de sangramento. Considerando os critérios de normalidade de ciclo menstrual da Federação Internacional de Ginecologia e Obstetricia, FIGO, 2007, observe o calendário menstrual acima e assinale a alternativa que apresenta a melhor conduta.","options":{"A":"Orienta que o ciclo está regular e que a duração do sangramento está normal.","B":"Confirma o diagnóstico de irregularidade menstrual e solicita FSH, prolactina e TSH.","C":"Confirma o diagnóstico de irregularidade menstrual e prescreve contraceptivo oral combinado.","D":"Orienta que o ciclo está regular, com duração aumentada. Prescreve anti-inflamatório não-esteroidal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234471","ankiGuid":"J-I5e{+]lU"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-dd8490f1cea50505","number":"0290h","sourceNumber":"0290h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Adolescente, 12 anos, procurou consulta médica por estar menstruando a cada 40 a 50 dias, com fluxo de duração de 9 dias. Nos 4 primeiros dias, elimina coágulos e necessita de 9 absorventes por dia. Antecedente pessoal: menarca há 15 meses. Nega atividade sexual. Exame físico: descorada 2+/4+, hímen íntegro, com saída de coágulos ao esforço (tosse). O diagnóstico é:","options":{"A":"Doença de von Willebrand.","B":"Sangramento uterino disfuncional.","C":"Púrpura trombocitopênica idiopática.","D":"Pólipo endometrial."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234472","ankiGuid":"CPgnij9LN1"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-2b3383c1bdf4153f","number":"0291h","sourceNumber":"0291h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Menina, 3 dias de vida, alimentação em seio materno exclusivo, trazida à consulta por sangramento vaginal discreto. Ao exame físico, identificada mínima quantidade de sangue no introito vaginal, sem lesões visíveis. Qual a conduta a seguir?","options":{"A":"Solicitar ultrassonografia abdominal e pélvica.","B":"Solicitar dosagem de FSH, TSH, Estradiol, 17-oh-progesterona e cortisol.","C":"Realizar vaginoscopia sob sedação.","D":"Realizar exame de tomografia pélvica.","E":"Observar clinicamente."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234473","ankiGuid":"M41H*Xj.Ax"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-bd0fde184cb3f78b","number":"0292h","sourceNumber":"0292h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Jéssica, 12 anos, última menstruação há 10 dias, foi levada por sua mãe em consulta com o médico de família por sangramento menstrual aumentado. Menarca há 6 meses, refere ciclo menstrual regular, porém com fluxo intenso, com duração de 9 dias desde a menarca. Já recebeu transfusão de concentrados de hemácias em episódios anteriores de sangramento menstrual. Hoje está sem sangramento ativo. Assinale a opção que contém o provável diagnóstico e a conduta para esse caso:","options":{"A":"Imaturidade do eixo hipotálamo-hipófise-ovário e uso de anti-inflamatórios.","B":"Síndrome dos ovários policísticos e uso de contraceptivos orais combinados.","C":"Doença de von Willebrand e uso de contraceptivos orais combinados.","D":"Hiperprolactinemia e uso de cabergolina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234474","ankiGuid":"GUyr%p:`X)"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-945a8db995b99b0c","number":"0293h","sourceNumber":"0293h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"A diarreia aquosa sem presença de sangue pode estar associada a diversos patógenos, EXCETO:","options":{"A":"Vibriocolerae.","B":"E.colienteropatogênica clássica.","C":"Rotavírus.","D":"Cepas de Shingella."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234475","ankiGuid":"e$5<Tq%7M?"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-6f232448301e94ae","number":"0294h","sourceNumber":"0294h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Mulher de 72 anos, hígida, refere saída de pequena quantidade de sangue pela vagina há um dia. Esse sangramento mancha a sua roupa, mas não apresenta coágulos e não é acompanhado de cólicas. A causa mais frequente dessa queixa clínica é:","options":{"A":"carcinossarcoma de endométrio.","B":"atrofia endometrial.","C":"pólipo endometrial.","D":"adenocarcinoma de endométrio.","E":"sarcoma uterino."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234476","ankiGuid":"GN1$rw~?ze"},{"id":"anki-ginecologia-sangramento-uterino-anormal-sua-4fed99d2e5310ee0","number":"0295h","sourceNumber":"0295h","collectionBlock":"anki:ginecologia-sangramento-uterino-anormal-sua","collectionLabel":"Anki · Sangramento Uterino Anormal (SUA)","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Sangramento Uterino Anormal (SUA)","subtopic":"","stem":"Paciente de 8 anos de idade é levada pela mãe à consulta ginecológica devido a sangramento vaginal anormal. Apresenta desenvolvimento mamário no estágio 3 de Tanner. Entre as hipóteses diagnósticas abaixo, marque a alternativa ERRADA para esse caso:","options":{"A":"Cisto funcional do ovário.","B":"Corpo estranho na vagina.","C":"Abuso sexual.","D":"Tumor das células germinativas do ovário."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Sangramento Uterino Anormal (SUA)","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Sangramento Uterino Anormal (SUA)","Anki"],"ankiNoteId":"1779713234477","ankiGuid":"B0ma;9W+z4"}]};
